import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../../styles/ManageUsers.css';

const ManageUsers = () => {
  const [users, setUsers] = useState([]);
  const [message, setMessage] = useState('');
  const [editingUser, setEditingUser] = useState(null);
  const [isCreating, setIsCreating] = useState(false); // Новый режим создания
  const [formData, setFormData] = useState({ name: '', email: '', role: '', password: '' }); // Добавил password для создания

  const fetchUsers = async () => {
    try {
      const res = await axios.get('/api/users', { withCredentials: true });
      setUsers(res.data);
    } catch (err) {
      console.error(err);
      setMessage('Ошибка загрузки пользователей');
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleDelete = async (id) => {
    if (!window.confirm('Удалить пользователя?')) return;
    try {
      await axios.delete(`/api/users/${id}`, { withCredentials: true });
      setMessage('Пользователь удалён');
      fetchUsers();
    } catch (err) {
      setMessage('Ошибка при удалении');
    }
  };

  const handleEditClick = (user) => {
    setEditingUser(user._id);
    setIsCreating(false);
    setFormData({ name: user.name, email: user.email, role: user.role, password: '' });
    setMessage('');
  };

  const handleCancel = () => {
    setEditingUser(null);
    setIsCreating(false);
    setFormData({ name: '', email: '', role: '', password: '' });
    setMessage('');
  };

  const handleChange = (e) => {
    setFormData(prev => ({ ...prev, [e.target.name]: e.target.value }));
  };

  // Обновление пользователя
  const handleUpdate = async (e) => {
    e.preventDefault();
    try {
      await axios.put(`/api/users/${editingUser}`, formData, { withCredentials: true });
      setMessage('Пользователь обновлён');
      setEditingUser(null);
      setFormData({ name: '', email: '', role: '', password: '' });
      fetchUsers();
    } catch (err) {
      setMessage(err.response?.data?.error || 'Ошибка при обновлении');
    }
  };

  // Создание пользователя
  const handleCreate = async (e) => {
    e.preventDefault();
    try {
      // При создании пароль обязателен
      if (!formData.password) {
        setMessage('Пароль обязателен для создания пользователя');
        return;
      }
      await axios.post('/api/users', formData, { withCredentials: true });
      setMessage('Пользователь создан');
      setIsCreating(false);
      setFormData({ name: '', email: '', role: '', password: '' });
      fetchUsers();
    } catch (err) {
      setMessage(err.response?.data?.error || 'Ошибка при создании пользователя');
    }
  };

  return (
    <div className="manage-users-page">
      <h2>Управление пользователями</h2>
      {message && <p>{message}</p>}

      {!editingUser && !isCreating && (
        <button onClick={() => { setIsCreating(true); setEditingUser(null); setFormData({ name: '', email: '', role: '', password: '' }); setMessage(''); }}>
          Создать пользователя
        </button>
      )}

      {(editingUser || isCreating) && (
        <form onSubmit={isCreating ? handleCreate : handleUpdate} className="edit-user-form">
          <input
            type="text"
            name="name"
            placeholder="Имя"
            value={formData.name}
            onChange={handleChange}
            required
          />
          <input
            type="email"
            name="email"
            placeholder="Email"
            value={formData.email}
            onChange={handleChange}
            required
          />
          <select name="role" value={formData.role} onChange={handleChange} required>
            <option value="">Выберите роль</option>
            <option value="admin">Админ</option>
            <option value="employee">Сотрудник</option>
            <option value="customer">Покупатель</option>
          </select>
          <input
            type="password"
            name="password"
            placeholder={isCreating ? "Пароль" : "Пароль (оставьте пустым, если не меняется)"}
            value={formData.password}
            onChange={handleChange}
            required={isCreating} // при редактировании пароль необязателен
          />
          <button type="submit">{isCreating ? 'Создать' : 'Сохранить'}</button>
          <button type="button" onClick={handleCancel}>Отмена</button>
        </form>
      )}

      {!editingUser && !isCreating && (
        <table className="users-table">
          <thead>
            <tr>
              <th>Имя</th>
              <th>Email</th>
              <th>Роль</th>
              <th>Действия</th>
            </tr>
          </thead>
          <tbody>
            {users.map(user => (
              <tr key={user._id}>
                <td>{user.name}</td>
                <td>{user.email}</td>
                <td>{user.role}</td>
                <td>
                  <button onClick={() => handleEditClick(user)}>Редактировать</button>{' '}
                  <button onClick={() => handleDelete(user._id)} className="delete-btn">Удалить</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default ManageUsers;
